<script setup>
import {ref,onMounted,computed,nextTick} from 'vue'
import {MessageCircle,Plus,RefreshCw,Smartphone,ShieldCheck,ArrowRight,Check,ChevronLeft,Settings2,FileText,Send,History,Search,CheckCircle2,AlertCircle,Copy,X} from 'lucide-vue-next'
import WhatsAppQrTemplates from './WhatsAppQrTemplates.vue'
import WhatsAppQrTest from './WhatsAppQrTest.vue'
import WhatsAppQrSession from './WhatsAppQrSession.vue'
import WhatsAppOnboarding from './WhatsAppOnboarding.vue'
const emit=defineEmits(['changed'])
const data=ref(null),busy=ref(false),error=ref(''),notice=ref(''),senderSids=ref({}),contentSids=ref({})
const tab=ref('numbers'),selectedId=ref(null),creating=ref(false),createStep=ref(1),templateEditor=ref(false),templateChannel=ref('qr'),testChannel=ref('qr')
const sender=ref({label:'',number:'+55',ownership:'external',provider:'qr',provider_sid:''})
const template=ref({name:'',language:'pt_BR',category:'UTILITY',body:'',variables:{}})
const examples=ref({}),values=ref({}),locked=ref(false),receipt=ref(null)
const message=ref({sender_id:'',template_id:'',contact_id:'',campaign_id:null,idempotency_key:crypto.randomUUID(),consent_confirmed:false,consent_evidence:''})
const historySearch=ref(''),historySender=ref(''),historyDirection=ref('')
const connected=computed(()=>!!data.value?.connection.configured)
const selected=computed(()=>data.value?.senders.find(s=>s.id===selectedId.value))
const online=computed(()=>data.value?.senders.filter(s=>s.status==='ONLINE').length||0)
const qrSenders=computed(()=>data.value?.senders.filter(s=>s.provider==='qr')||[])
const twilioSenders=computed(()=>data.value?.senders.filter(s=>s.provider==='twilio')||[])
const approved=computed(()=>data.value?.templates.filter(t=>t.approval_status==='approved')||[])
const eligible=computed(()=>data.value?.contacts.filter(c=>c.consent&&!c.suppressed_at&&!c.replied_at)||[])
const selectedTemplate=computed(()=>data.value?.templates.find(t=>t.id===message.value.template_id))
const keys=text=>[...new Set([...text.matchAll(/\{\{([1-9][0-9]?)\}\}/g)].map(m=>m[1]))].sort((a,b)=>Number(a)-Number(b))
const variableLabel=key=>'Exemplo da variável '+key+' · {{'+key+'}}'
const exampleKeys=computed(()=>keys(template.value.body)),valueKeys=computed(()=>keys(selectedTemplate.value?.body||''))
const preview=(body,vars)=>(body||'').replace(/\{\{([1-9][0-9]?)\}\}/g,(m,k)=>vars[k]||'['+'Variável '+k+']')
const filteredMessages=computed(()=>data.value?.messages.filter(m=>(!historySender.value||String(m.sender_id)===historySender.value)&&(!historyDirection.value||m.direction===historyDirection.value)&&(!historySearch.value.trim()||[m.body,m.from_number,m.to_number].join(' ').toLocaleLowerCase('pt-BR').includes(historySearch.value.trim().toLocaleLowerCase('pt-BR'))))||[])
const tabs=[['numbers','Números conectados',Smartphone],['templates','Templates',FileText],['test','Teste de envio',Send],['history','Histórico',History]]
const labels={ONLINE:'Conectado',OFFLINE:'Desconectado',PENDING:'Em análise',CREATING:'Em configuração',unverified:'Conexão pendente',draft:'Rascunho',creating:'Publicação iniciada',created:'Publicado na Twilio',publication_unknown:'Publicação sem confirmação',rejected_request:'Publicação recusada',not_submitted:'Aprovação não solicitada',submitting:'Solicitação iniciada',submission_unknown:'Solicitação sem confirmação',received:'Recebida',pending:'Em análise',approved:'Aprovado',rejected:'Rejeitado',paused:'Pausado',disabled:'Desativado',unknown:'Sem confirmação',sending:'Tentativa reservada',accepted:'Aceita pelo provedor',queued:'Na fila do provedor',sending_provider:'Em envio',sent:'Enviada',delivered:'Entregue',read:'Lida',failed:'Falhou',undelivered:'Não entregue',cancelled:'Cancelada'}
const label=s=>labels[s]||s
const tone=s=>['ONLINE','approved','delivered','read'].includes(s)?'good':['failed','undelivered','rejected','OFFLINE','disabled','rejected_request'].includes(s)?'bad':'pending'
const channel=s=>s.provider==='qr'?'QR Code':'API oficial · Twilio'
function date(value){if(!value)return 'Ainda não consultado';const d=new Date(value.includes('T')?value:value.replace(' ','T')+'Z');return Number.isNaN(d.getTime())?value:d.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}
async function api(path='',method='GET',body){const r=await fetch('/api/voice/whatsapp'+path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw new Error(d.errors?Object.values(d.errors).flat().join(' · '):d.message||'Não foi possível concluir.');return d}
async function refresh(){const first=!data.value;data.value=await api();if(!selected.value)selectedId.value=(data.value.senders.find(s=>s.status==='ONLINE')||data.value.senders[0])?.id||null;if(first&&twilioSenders.value.length&&!qrSenders.value.length){templateChannel.value='twilio';testChannel.value='twilio'}emit('changed')}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function action(path,body={}){await run(async()=>{await api(path,'POST',body);await refresh();notice.value='Estado atualizado.'})}
async function focus(id){await nextTick();document.getElementById(id)?.focus()}
function openCreate(){tab.value='numbers';creating.value=true;createStep.value=1;focus('wa-create-title')}
function openTemplates(provider){templateChannel.value=provider;tab.value='templates'}
async function addSender(){await run(async()=>{const saved=await api('/senders','POST',{...sender.value,number:sender.value.number.replace(/[\s()-]/g,''),provider_sid:sender.value.provider==='twilio'?(sender.value.provider_sid||null):null});selectedId.value=saved.id;sender.value={label:'',number:'+55',ownership:'external',provider:'qr',provider_sid:''};creating.value=false;createStep.value=1;await refresh();notice.value='Número cadastrado. Conclua a conexão no painel ao lado.';focus('wa-connection-title')})}
async function bindSender(s){await run(async()=>{await api('/senders/'+s.id,'PUT',{provider_sid:senderSids.value[s.id]});await refresh();notice.value='Identificador vinculado. Agora verifique a conexão na Twilio.'})}
function variableValues(list,source){return Object.fromEntries(list.map(k=>[k,source[k]||'']))}
function addVariable(){const n=Array.from({length:10},(_,i)=>String(i+1)).find(k=>!exampleKeys.value.includes(k));if(n)template.value.body+=' {{'+n+'}}'}
async function addTemplate(){await run(async()=>{await api('/templates','POST',{...template.value,variables:variableValues(exampleKeys.value,examples.value)});template.value.name='';template.value.body='';examples.value={};templateEditor.value=false;await refresh();notice.value='Rascunho salvo. O próximo passo é publicar na Twilio e solicitar aprovação.'})}
async function addQrTemplate(payload,done){await run(async()=>{await api('/qr/templates','POST',payload);await refresh();done();notice.value='Modelo QR salvo. Você já pode selecioná-lo na etapa WhatsApp da cadência.'})}
function interactive(m){try{return typeof m.interactive==='string'?JSON.parse(m.interactive):m.interactive}catch{return null}}
function chooseTemplate(){values.value={...(selectedTemplate.value?.variables||{})}}
async function send(){await run(async()=>{locked.value=true;receipt.value=await api('/messages','POST',{...message.value,variables:variableValues(valueKeys.value,values.value)});await refresh();notice.value='Tentativa registrada: '+label(receipt.value.status)+'. Acompanhe a entrega no histórico.'})}
function newMessage(){message.value={...message.value,idempotency_key:crypto.randomUUID(),consent_confirmed:false,consent_evidence:''};receipt.value=null;locked.value=false;notice.value='Nova tentativa preparada. Confira o histórico antes de enviar novamente.'}
async function copyUrl(){try{await navigator.clipboard.writeText(data.value.connection.inbound_url);notice.value='Endereço de recebimento copiado.'}catch{error.value='Não foi possível copiar. Selecione e copie o endereço exibido.'}}
onMounted(()=>run(refresh))
</script>
<template>
 <section class="wa-panel" :aria-busy="busy">
  <header class="wa-heading"><div class="wa-brand-icon"><MessageCircle :size="27"/></div><div class="wa-heading-copy"><span class="eyebrow">CONECTE. PERSONALIZE. CONVERSE.</span><h1>Seu WhatsApp, organizado.</h1><p>Gerencie seus números e prepare as mensagens das suas cadências.</p></div><button class="secondary wa-refresh" :disabled="busy" @click="run(refresh)"><RefreshCw :size="15" :class="{spinning:busy}"/>Atualizar</button></header>
  <div v-if="error" role="alert" class="error">{{error}}</div><p v-if="notice" role="status" class="wa-notice"><CheckCircle2 :size="17"/>{{notice}}</p>
  <div v-if="!data" class="wa-loading"><p>{{error?'Não foi possível carregar as configurações. Use Atualizar para tentar novamente.':'Carregando seus números e mensagens…'}}</p></div>
  <template v-else>
   <div class="wa-overview" aria-label="Resumo do WhatsApp"><div><span class="wa-dot" :class="online?'good':'pending'"></span><strong>{{online}}</strong><span>{{online===1?'número conectado':'números conectados'}}</span><small>de {{data.senders.length}} cadastrados</small></div><div><FileText :size="17"/><strong>{{(data.qr_templates?.length||0)+data.templates.length}}</strong><span>templates salvos</span></div><a href="#/conversations">Abrir caixa de atendimento <ArrowRight :size="15"/></a></div>
   <nav class="wa-tabs" aria-label="Configurações do WhatsApp"><button v-for="[key,title,icon] in tabs" :key="key" :aria-pressed="tab===key" :class="{selected:tab===key}" :disabled="busy" @click="tab=key"><component :is="icon" :size="17"/>{{title}}</button></nav>

   <section v-show="tab==='numbers'" aria-label="Números conectados">
    <div class="wa-section-heading"><div><h3>Seus números</h3><p>Escolha um número para ver a conexão e o próximo passo.</p></div><button class="primary" :disabled="busy" @click="openCreate"><Plus :size="16"/>Conectar número</button></div>
    <article v-show="creating" class="wa-box wa-create">
     <div class="wa-section-heading"><div><span class="eyebrow">PASSO {{createStep}} DE 2</span><h3 id="wa-create-title" tabindex="-1">{{createStep===1?'Como você quer conectar?':'Identifique seu número'}}</h3></div><button class="wa-icon-button" type="button" aria-label="Fechar cadastro de número" :disabled="busy" @click="creating=false"><X :size="20"/></button></div>
     <div v-show="createStep===1"><div class="wa-provider-options"><button type="button" :aria-pressed="sender.provider==='qr'" :class="{chosen:sender.provider==='qr'}" @click="sender.provider='qr';sender.provider_sid='' "><Smartphone :size="26"/><strong>Conectar pelo celular</strong><span>Leia um QR Code em Aparelhos conectados no seu WhatsApp.</span><small>Dispositivo vinculado · botões experimentais</small><Check v-if="sender.provider==='qr'" :size="18" class="wa-choice-check"/></button><button type="button" :aria-pressed="sender.provider==='twilio'" :class="{chosen:sender.provider==='twilio'}" @click="sender.provider='twilio'"><ShieldCheck :size="26"/><strong>Usar API oficial</strong><span>Cadastre ou conecte seu número pelo assistente oficial.</span><small>Twilio · templates com aprovação da Meta</small><Check v-if="sender.provider==='twilio'" :size="18" class="wa-choice-check"/></button></div><div class="wa-actions"><button type="button" class="primary" @click="createStep=2;focus('wa-sender-name')">Continuar <ArrowRight :size="16"/></button></div></div>
     <form v-show="createStep===2" @submit.prevent="addSender"><p class="wa-muted">{{sender.provider==='qr'?'Após cadastrar, leia o QR Code para concluir a conexão.':'Após cadastrar, escolha Minha empresa ou Empresa cliente no assistente.'}}</p><div class="wa-grid"><label>Nome para identificar este número<input id="wa-sender-name" v-model="sender.label" required maxlength="160" placeholder="Ex.: Comercial Zyrex"></label><label>Número do WhatsApp<input v-model="sender.number" aria-label="Número do WhatsApp" type="tel" required pattern="\+[0-9\s\(\)\-]{8,25}" placeholder="+55 11 99999-0000"><small>Inclua +, código do país, DDD e número.</small></label></div><details v-if="sender.provider==='twilio'" class="wa-details"><summary>Já tenho o identificador do remetente</summary><label>Sender SID da Twilio<input v-model="sender.provider_sid" placeholder="XE…" pattern="XE[0-9a-fA-F]{32}"><small>Opcional neste passo. Você pode vincular depois.</small></label></details><details class="wa-details"><summary>Origem da linha</summary><label>Operadora do número<select aria-label="Operadora do número" v-model="sender.ownership"><option value="external">Outra operadora</option><option value="twilio">Twilio</option></select></label></details><div class="wa-actions"><button type="button" class="secondary" :disabled="busy" @click="createStep=1"><ChevronLeft :size="16"/>Voltar</button><button class="primary" :disabled="busy">Cadastrar e continuar <ArrowRight :size="16"/></button></div></form>
    </article>
    <div v-if="!data.senders.length&&!creating" class="wa-empty wa-box"><Smartphone :size="36"/><h3>Seu primeiro número começa aqui.</h3><p>Conecte pelo celular ou use a API oficial da Twilio.</p><button class="primary" @click="openCreate"><Plus :size="16"/>Conectar meu WhatsApp</button></div>
    <div v-if="data.senders.length" class="wa-number-layout">
     <div class="wa-number-list" aria-label="Escolher número"><button v-for="s in data.senders" :key="s.id" type="button" class="wa-number-card" :class="{chosen:selectedId===s.id}" :aria-pressed="selectedId===s.id" @click="selectedId=s.id"><span class="wa-number-icon"><Smartphone v-if="s.provider==='qr'" :size="22"/><ShieldCheck v-else :size="22"/></span><span class="wa-number-copy"><strong>{{s.label}}</strong><span>{{s.number}}</span><small>{{channel(s)}}</small></span><span class="wa-badge" :class="tone(s.status)"><span class="wa-dot"></span>{{label(s.status)}}</span><ArrowRight class="wa-card-arrow" :size="16"/></button></div>
     <article v-if="selected" class="wa-box wa-connection" :key="selected.id">
      <div class="wa-section-heading"><span class="eyebrow">{{channel(selected)}}</span><span class="wa-badge" :class="tone(selected.status)">{{label(selected.status)}}</span></div><h3 id="wa-connection-title" tabindex="-1">{{selected.label}}</h3><p class="wa-phone">{{selected.number}}</p>
      <WhatsAppQrSession v-if="selected.provider==='qr'" :sender="selected" @changed="run(refresh)"/>
      <template v-else>
       <WhatsAppOnboarding :sender="selected" @changed="run(refresh)"/>
       <details class="wa-details"><summary>Vínculo avançado por Sender SID</summary><p>Use somente se já tem o identificador do remetente cadastrado na Twilio.</p><form v-if="!selected.provider_sid" @submit.prevent="bindSender(selected)"><label>Identificador do remetente · Sender SID<input v-model="senderSids[selected.id]" required pattern="XE[0-9a-fA-F]{32}" placeholder="XE…"></label><button class="secondary" :disabled="busy">Vincular remetente</button></form><button v-else class="secondary" :disabled="busy||!connected" @click="action('/senders/'+selected.id+'/sync')">Verificar conexão na Twilio</button></details>
      </template>
      <p class="wa-sync">Última verificação: {{date(selected.synced_at)}}</p>
      <div class="wa-next"><span class="wa-mini-icon"><FileText :size="19"/></span><div><strong>Prepare a mensagem deste canal</strong><p>{{selected.provider==='qr'?'Use texto personalizado e modelos com até três botões.':'Crie um template e acompanhe a aprovação da Meta.'}}</p><button class="wa-text-button" @click="openTemplates(selected.provider)">Ir para templates <ArrowRight :size="15"/></button></div></div>
     </article>
    </div>
    <aside class="wa-cadence-tip"><Settings2 :size="20"/><div><strong>Qual número vai enviar na cadência?</strong><p>Abra a cadência e selecione o remetente no cartão <b>Enviar WhatsApp</b>. Você pode usar o número de voz, se conectado ao WhatsApp, ou escolher outro número.</p></div><a href="#/cadences">Ver cadências <ArrowRight :size="15"/></a></aside>
   </section>

   <section v-show="tab==='templates'" aria-label="Templates de WhatsApp">
    <div class="wa-section-heading"><div><h3>Mensagens que se adaptam a cada contato</h3><p>Escolha o canal e prepare seus modelos antes de usá-los na cadência.</p></div></div>
    <div class="wa-channel-switch" aria-label="Canal dos templates"><button :aria-pressed="templateChannel==='qr'" :class="{selected:templateChannel==='qr'}" @click="templateChannel='qr'"><Smartphone :size="16"/>QR Code <span>{{data.qr_templates?.length||0}}</span></button><button :aria-pressed="templateChannel==='twilio'" :class="{selected:templateChannel==='twilio'}" @click="templateChannel='twilio'"><ShieldCheck :size="16"/>API oficial · Twilio <span>{{data.templates.length}}</span></button></div>
    <WhatsAppQrTemplates v-show="templateChannel==='qr'" :templates="data.qr_templates||[]" :contacts="data.contacts" :busy="busy" @create="addQrTemplate"/>
    <div v-show="templateChannel==='twilio'">
     <div class="wa-template-guide"><div><span>1</span>Salvar rascunho</div><ArrowRight :size="16"/><div><span>2</span>Publicar na Twilio</div><ArrowRight :size="16"/><div><span>3</span>Solicitar aprovação</div></div>
     <div class="wa-section-heading"><div><h3>Templates da API oficial</h3><p>A Meta analisa o texto e a categoria antes do uso.</p></div><button class="primary" :disabled="busy" @click="templateEditor=!templateEditor;if(templateEditor)focus('wa-template-name')"><Plus :size="16"/>{{templateEditor?'Fechar editor':'Novo template'}}</button></div>
     <form v-show="templateEditor" class="wa-box" @submit.prevent="addTemplate"><h3>Novo template de texto</h3><div class="wa-grid"><div><label>Nome do template<input id="wa-template-name" aria-label="Nome do template" v-model="template.name" required pattern="[a-z][a-z0-9_]{2,99}" placeholder="retorno_comercial"><small>Use letras minúsculas, números e sublinhado.</small></label><div class="wa-grid"><label>Idioma<select aria-label="Idioma" v-model="template.language"><option value="pt_BR">Português (Brasil)</option><option value="en">Inglês</option><option value="es">Espanhol</option></select></label><label>Categoria<select aria-label="Categoria" v-model="template.category"><option value="UTILITY">Utilidade</option><option value="MARKETING">Marketing</option></select></label></div><label>Texto do template<textarea v-model="template.body" required maxlength="1024" rows="5" :placeholder="'Olá, {{1}}. Qual é o melhor horário para conversarmos?'"/></label><button type="button" class="secondary" :disabled="exampleKeys.length>=10" @click="addVariable"><Plus :size="14"/>Adicionar variável</button><div v-if="exampleKeys.length" class="wa-variable-fields"><h4>Exemplos para aprovação</h4><p>Preencha um exemplo para cada informação que muda entre os contatos.</p><label v-for="key in exampleKeys" :key="key">{{variableLabel(key)}}<input v-model="examples[key]" required maxlength="500" :placeholder="key==='1'?'Ex.: Ana':'Ex.: pedido 123'"/></label></div></div><aside class="wa-message-preview"><span class="eyebrow">PRÉVIA DA MENSAGEM</span><div class="wa-bubble">{{preview(template.body,examples)||'Seu texto personalizado aparecerá aqui.'}}<small>Exemplo ilustrativo</small></div><p>Nos envios, os valores podem ser preenchidos com os dados de cada cliente.</p></aside></div><div class="wa-actions"><button class="primary" :disabled="busy">Salvar rascunho</button><small>Salvar não publica nem envia a mensagem.</small></div></form>
     <div v-if="!data.templates.length&&!templateEditor" class="wa-empty wa-box"><FileText :size="32"/><h3>Nenhum template oficial ainda</h3><p>Crie o texto e acompanhe a publicação e a aprovação por aqui.</p><button class="secondary" @click="templateEditor=true;focus('wa-template-name')">Criar primeiro template</button></div>
     <div class="wa-template-list"><article v-for="t in data.templates" :key="t.id" class="wa-box"><div class="wa-section-heading"><strong>{{t.name}}</strong><span class="wa-badge" :class="tone(t.approval_status)">{{label(t.approval_status)}}</span></div><small>{{t.language==='pt_BR'?'Português (Brasil)':t.language}} · {{t.category==='MARKETING'?'Marketing':'Utilidade'}} · {{label(t.state)}}</small><p class="wa-body">{{t.body}}</p><p v-if="t.rejection_reason" class="error">{{t.rejection_reason}}</p><div class="wa-actions"><button v-if="['draft','rejected_request'].includes(t.state)" class="secondary" :disabled="busy||!connected" @click="action('/templates/'+t.id+'/publish')">Publicar na Twilio</button><button v-if="t.content_sid&&t.approval_status==='not_submitted'" class="primary" :disabled="busy||!connected" @click="action('/templates/'+t.id+'/approval',{submit:true})">Solicitar aprovação</button><button v-if="t.content_sid" class="secondary" :disabled="busy||!connected" @click="action('/templates/'+t.id+'/approval',{submit:false})">Consultar aprovação</button></div><p v-if="!connected" class="wa-muted">Configure as credenciais do WhatsApp Twilio para publicar e consultar.</p><form v-if="['creating','publication_unknown'].includes(t.state)" @submit.prevent="action('/templates/'+t.id+'/reconcile',{content_sid:contentSids[t.id]})"><p>Publicação sem confirmação. Confira o conteúdo no console antes de repetir.</p><label>Content SID para conciliar<input v-model="contentSids[t.id]" pattern="HX[0-9a-fA-F]{32}" required placeholder="HX…"></label><button class="secondary" :disabled="busy||!connected">Conciliar template</button></form></article></div>
     <p v-if="data.templates.length>=100" class="wa-muted">Exibindo os últimos 100 templates.</p>
    </div>
   </section>

   <section v-show="tab==='test'" aria-label="Teste de envio">
    <div class="wa-section-heading"><div><h3>Confira antes de usar na cadência</h3><p>Escolha o canal e envie uma mensagem para um contato autorizado.</p></div></div>
    <div class="wa-callout"><AlertCircle :size="19"/><p><strong>Este teste envia uma mensagem real.</strong> Confira o destinatário e a autorização antes de confirmar. A API oficial pode gerar cobrança.</p></div>
    <div class="wa-channel-switch" aria-label="Canal do teste"><button :aria-pressed="testChannel==='qr'" :class="{selected:testChannel==='qr'}" @click="testChannel='qr'"><Smartphone :size="16"/>QR Code</button><button :aria-pressed="testChannel==='twilio'" :class="{selected:testChannel==='twilio'}" @click="testChannel='twilio'"><ShieldCheck :size="16"/>API oficial · Twilio</button></div>
    <div v-show="testChannel==='qr'"><WhatsAppQrTest v-if="qrSenders.length" :senders="data.senders" :contacts="data.contacts" :templates="data.qr_templates||[]" :campaigns="data.campaigns" @changed="run(refresh)"/><div v-else class="wa-empty wa-box"><Smartphone :size="30"/><h3>Conecte um número por QR Code</h3><p>Depois você poderá testar o texto e os botões no celular.</p><button class="primary" @click="openCreate">Conectar número</button></div></div>
    <div v-show="testChannel==='twilio'">
     <div class="wa-prerequisites"><span :class="{complete:connected}"><CheckCircle2 :size="16"/>Conta configurada</span><span :class="{complete:twilioSenders.some(s=>s.status==='ONLINE')}"><CheckCircle2 :size="16"/>Número conectado</span><span :class="{complete:approved.length}"><CheckCircle2 :size="16"/>Template aprovado</span><span :class="{complete:eligible.length}"><CheckCircle2 :size="16"/>Contato elegível</span></div>
     <p v-if="!connected||!twilioSenders.some(s=>s.status==='ONLINE')||!approved.length" class="wa-muted">Complete os itens acima em Números conectados e Templates para liberar o envio.</p>
     <form class="wa-box" @submit.prevent="send"><h3>Mensagem pela API oficial</h3><fieldset :disabled="busy||locked||!connected"><div class="wa-grid"><label>Remetente do envio<select aria-label="Remetente do envio" v-model="message.sender_id" required><option value="">Selecione um número conectado</option><option v-for="s in twilioSenders" :key="s.id" :value="s.id" :disabled="s.status!=='ONLINE'">{{s.label}} · {{s.number}}{{s.status!=='ONLINE'?' · '+label(s.status):''}}</option></select></label><label>Template aprovado<select aria-label="Template aprovado" v-model="message.template_id" required @change="chooseTemplate"><option value="">Selecione o template</option><option v-for="t in approved" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>Contato autorizado<select aria-label="Contato autorizado" v-model="message.contact_id" required><option value="">Selecione o destinatário</option><option v-for="c in eligible" :key="c.id" :value="c.id">{{c.name}} · {{c.phone}}</option></select></label><label>Campanha vinculada · opcional<select aria-label="Campanha vinculada · opcional" v-model="message.campaign_id"><option :value="null">Teste avulso</option><option v-for="c in data.campaigns" :key="c.id" :value="c.id">{{c.name}}</option></select></label></div><p v-if="!eligible.length" class="wa-muted">Não há contatos elegíveis para este teste. Contatos que responderam ou solicitaram saída não aparecem.</p><div v-if="selectedTemplate" class="wa-grid"><div><label v-for="key in valueKeys" :key="key">{{'Valor da variável '+key}}<input v-model="values[key]" required maxlength="500"/></label></div><div class="wa-bubble">{{preview(selectedTemplate.body,values)}}</div></div><label>Evidência da autorização deste envio<textarea v-model="message.consent_evidence" minlength="8" maxlength="1000" required rows="2" placeholder="Ex.: contato autorizou o teste por mensagem hoje."/></label><label class="wa-check"><input type="checkbox" v-model="message.consent_confirmed" required>Confirmo a autorização do destinatário para este teste de WhatsApp.</label></fieldset><div class="wa-actions"><button v-if="!locked" class="primary" :disabled="busy||!connected||!approved.length||!eligible.length||!twilioSenders.some(s=>s.status==='ONLINE')"><Send :size="15"/>Enviar teste real</button><button v-else-if="!receipt" type="button" class="secondary" :disabled="busy" @click="send">Consultar ou retomar a mesma tentativa</button><button v-if="locked" type="button" class="secondary" :disabled="busy" @click="newMessage">Preparar outra mensagem</button></div><p v-if="receipt" role="status">Estado: {{label(receipt.status)}}.</p><p v-if="locked" class="wa-muted">A tentativa mantém a mesma identificação. Se estiver sem confirmação, consulte o histórico antes de criar outro envio.</p></form>
     <details class="wa-details wa-box"><summary>Destinos e limites de teste da API</summary><p>Destinos autorizados: {{data.connection.allowed_recipients?.join(', ')||'Nenhum configurado'}}.</p><p>Limite do canal: {{data.connection.daily_limit}} tentativas por dia (UTC). Outros limites da operação também se aplicam.</p></details>
    </div>
   </section>

   <section v-show="tab==='history'" aria-label="Histórico de mensagens">
    <div class="wa-section-heading"><div><h3>Acompanhe cada mensagem</h3><p>Últimos 100 registros, entre envios e recebimentos. Horários no seu fuso local.</p></div><a class="secondary" href="#/cadences/reports">Relatórios por cadência <ArrowRight :size="15"/></a></div>
    <div class="wa-history-filters"><label class="wa-search"><span>Buscar mensagem ou telefone</span><div><Search :size="17"/><input v-model="historySearch" type="search" placeholder="Texto ou número…"></div></label><label>Número conectado<select aria-label="Número conectado" v-model="historySender"><option value="">Todos os números</option><option v-for="s in data.senders" :key="s.id" :value="String(s.id)">{{s.label}}</option></select></label><label>Direção<select aria-label="Direção" v-model="historyDirection"><option value="">Todas</option><option value="outbound">Enviadas</option><option value="inbound">Recebidas</option></select></label></div>
    <div class="wa-box wa-history"><p v-if="!filteredMessages.length" class="wa-empty">{{data.messages.length?'Nenhuma mensagem corresponde aos filtros.':'As mensagens aparecerão aqui após o primeiro envio ou recebimento.'}}</p><div v-else class="wa-table"><table><thead><tr><th>Mensagem</th><th>Origem e destino</th><th>Status</th><th>Quando</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody><tr v-for="m in filteredMessages" :key="m.id"><td><small>{{m.direction==='inbound'?'RECEBIDA':'ENVIADA'}} · {{m.provider==='qr'?'QR Code':'Twilio'}}</small><p v-if="m.body" class="wa-body">{{m.body}}</p><small v-if="interactive(m)?.buttons">Botões: {{interactive(m).buttons.map(b=>b.label).join(' · ')}}</small><small v-if="interactive(m)?.kind==='button_reply'" class="wa-button-reply">Resposta de botão: {{interactive(m).label||interactive(m).id}}{{interactive(m).matched_message_id?' · vinculada ao envio':' · sem vínculo confirmado'}}</small></td><td><span>{{m.from_number}}</span><small>↓ {{m.to_number}}</small></td><td><span class="wa-badge" :class="tone(m.status)">{{label(m.status)}}</span><small v-if="m.error_code">Código: {{m.error_code}}</small></td><td>{{date(m.created_at)}}</td><td><button v-if="m.direction==='outbound'&&m.provider==='twilio'&&m.provider_sid" class="secondary" :disabled="busy||!connected" @click="action('/messages/'+m.id+'/reconcile',{message_sid:m.provider_sid})">Consultar entrega</button></td></tr></tbody></table></div></div><p class="wa-muted">Respostas e pedidos de saída interrompem a abordagem. Para conversar com o cliente, use a caixa de atendimento.</p>
   </section>
  </template>
 </section>
